import{_ as n,C as r,c as l,o as i,aa as s,G as t}from"./chunks/framework.ByRpVre_.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"TownyAdvanced","link":"/wiki/TownyAdvanced"},{"title":"misc","link":""},{"title":"","link":"/wiki/TownyAdvanced/misc/plugins-using-the-towny-api"}]},"headers":[],"relativePath":"wiki/TownyAdvanced/misc/plugins-using-the-towny-api.md","filePath":"wiki/TownyAdvanced/misc/plugins-using-the-towny-api.md"}'),p={name:"wiki/TownyAdvanced/misc/plugins-using-the-towny-api.md"};function w(c,e,h,g,y,u){const o=r("NolebaseGitContributors"),a=r("NolebaseGitChangelog");return i(),l("div",null,[e[0]||(e[0]=s('<h2 id="使用了-towny-api-的插件" tabindex="-1">使用了 Towny API 的插件 <a class="header-anchor" href="#使用了-towny-api-的插件" aria-label="Permalink to &quot;使用了 Towny API 的插件&quot;">​</a></h2><p>如下插件通过 Towny API 与 Towny 兼容或联动。</p><ul><li><p><a href="https://www.spigotmc.org/resources/townywars.80038/" target="_blank" rel="noreferrer">TownyWars</a> - 适用于 Towny 的简单战争插件。（已停更）（建议使用 <a href="https://github.com/TownyAdvanced/SiegeWar" target="_blank" rel="noreferrer">SiegeWar</a>/<a href="https://github.com/TownyAdvanced/FlagWar" target="_blank" rel="noreferrer">FlagWar</a>/<a href="https://townyadvanced.github.io/eventwar.html" target="_blank" rel="noreferrer">EventWar</a>）</p></li><li><p><a href="http://www.palmergames.com/file-repo/Lockette/1.7.12/" target="_blank" rel="noreferrer">Lockette</a> - Towny 可以在 <code>/plot clear</code> 期间清除地皮上的牌子锁。</p></li><li><p><a href="https://www.spigotmc.org/resources/chestshop.51856/" target="_blank" rel="noreferrer">ChestShop</a> - 只允许在 Towny 的商店地皮上创建箱子商店。需要安装 <a href="https://github.com/TownyAdvanced/ChestShop-towny/releases" target="_blank" rel="noreferrer">ChestShop-Towny</a>。</p></li><li><p><a href="http://dev.bukkit.org/bukkit-plugins/ecocreature/" target="_blank" rel="noreferrer">ecoCreature</a> - 根据所在城镇提升或降低杀怪获得的钱。</p></li><li><p><a href="http://dev.bukkit.org/bukkit-plugins/faction-mobs" target="_blank" rel="noreferrer">Faction Mobs</a> - 这个插件（原名为 Towny Mobs）晕奴性你生成指定阵营的怪物。它们会攻击敌对阵营的玩家或怪物。</p></li><li><p><a href="https://github.com/TownyAdvanced/Dynmap-Towny/releases" target="_blank" rel="noreferrer">Dynmap-Towny</a> - 这个插件提供了一种在 Dynmap 地图上显示 Towny 城镇及国家的方式。需要同时安装 Dynmap 和 Towny Advanced。除此之外它也直接使用了 Towny API。</p></li><li><p><a href="https://github.com/TownyAdvanced/MapTowny" target="_blank" rel="noreferrer">MapTowny</a> - 这个插件提供了 Dynmap/BlueMap/SquareMap/Pl3xMap 支持，同时为开发者提供了一个更新更好的 API。</p></li><li><p><a href="https://github.com/TownyAdvanced/mcMMO-Towny/releases/tag/1.0.1" target="_blank" rel="noreferrer">McMMO-Towny</a> - 允许在 Towny 城镇中获得 McMMO 的经验。</p></li><li><p><a href="http://dev.bukkit.org/bukkit-plugins/trails/" target="_blank" rel="noreferrer">Trails</a> - Trails 是一款非常契合 RPG 风格的插件，可以让玩家频繁走过的路从泥土变成石头铺就。可以限制为只在郊区中生效。</p></li><li><p><a href="http://www.spigotmc.org/resources/gchat-free-towny-version.6291/" target="_blank" rel="noreferrer">GChat</a> - JSON 风格的聊天插件，兼容 Towny Advanced。插件以 JSON 格式为服主提供了集美观与功能于一身的聊天栏。这是一个轻量化的插件，能也只能与 Towny Advanced 搭配使用，足以替代默认的 TownyChat.jar。</p></li><li><p><a href="https://www.spigotmc.org/resources/townygui.35745/" target="_blank" rel="noreferrer">TownyGUI</a> - 为 Towny 的命令设计的菜单插件，快去看看吧！</p></li><li><p><a href="https://www.spigotmc.org/resources/townyflight.50360/" target="_blank" rel="noreferrer">TownyFlight</a> - 一款免费的飞行插件，作者是 LlmDl。</p></li><li><p><a href="https://www.spigotmc.org/resources/towny-tne.71240/" target="_blank" rel="noreferrer">Towny-TNE</a> - 将 Towny 位置与 The New Economy 特性兼容的插件，作者是 LlmDl。</p></li><li><p><a href="https://www.spigotmc.org/resources/rpg-leveled-mobs.71301/" target="_blank" rel="noreferrer">RPG Leveled Mobs</a> - 一款为怪物带来了 RPG 等级的插件，作者是 iomatix。</p></li><li><p><a href="https://www.spigotmc.org/resources/huntplayer.71789/" target="_blank" rel="noreferrer">HuntPlayer</a> - 揭示其他玩家信息的插件。包括 Towny 地皮。适用于 PVP 服务器，作者是 LlmDl。</p></li><li><p><a href="https://www.spigotmc.org/resources/townymarket-sell-and-buy-towny.71786/" target="_blank" rel="noreferrer">TownyMarket</a> - 允许将城镇在服务器上挂售，作者是 Dzirt。</p></li><li><p><a href="https://www.spigotmc.org/resources/townylocations.76778/" target="_blank" rel="noreferrer">TownyLocations</a> - 允许浏览其他玩家地皮的插件，若有权限还可传送。</p></li><li><p><a href="https://www.spigotmc.org/resources/discordtownylink.78179/" target="_blank" rel="noreferrer">DiscordTownyLink</a> - 通过 Discord 管理玩家职位，作者是 Coco10203。</p></li><li><p><a href="https://www.spigotmc.org/resources/cropclick.69480/" target="_blank" rel="noreferrer">CropClick</a> - 允许玩家点击收割农作物。这个插件兼容 Towny 保护区域内玩家的交互，作者是 BakuPlayz。</p></li></ul><ul><li>A plugin that lets players click crops and receive the drops. CropClick uses Towny to allow/deny players to click crops, by .</li></ul><ul><li><p><a href="https://www.spigotmc.org/resources/towny-menu-update.103260/" target="_blank" rel="noreferrer">TownyMenu</a> - 这是一个简单的插件，旨在为 Towny 添光增色。有了这个插件，你就不再需要输入冗长枯燥的命令。从城镇权限、税收、居民等级，再到地皮价格与类型都可以在简单、强引导性的菜单中完成。</p></li><li><p><a href="https://github.com/Chicken/BlueMap-Towny" target="_blank" rel="noreferrer">BlueMap-Towny</a> - 在你的 <a href="https://www.spigotmc.org/resources/bluemap.83557/" target="_blank" rel="noreferrer">BlueMap</a> 上显示 Towny 的城镇！</p></li><li><p><a href="https://www.spigotmc.org/resources/townymission-a-must-have-addition-to-towny-servers.94472/" target="_blank" rel="noreferrer">TownyMissions</a> - 这个任务插件可以在服务器上产生良性竞争。</p></li><li><p><a href="https://github.com/honnisha/towny-info" target="_blank" rel="noreferrer">Towny-Info</a> - 基于告示牌显示城镇与国家排行榜，拥有点击传送等多种功能，作者是 Honnisha。</p></li><li><p><a href="https://www.spigotmc.org/resources/1-17-x-1-18-x-notquests-%E2%9A%A1-solid-quest-system-%E2%9C%85.95872/" target="_blank" rel="noreferrer">NotQuests</a> - 有 Towny 联动的任务插件（目前，可以要求玩家处于某个国家中才可接取任务。允许你制作不同国家的阵营任务）</p></li><li><p><a href="https://github.com/lofi-enjoyer/TownyElections" target="_blank" rel="noreferrer">TownyElections</a> - 觉得默认的 Towny 机制太专治？这个选举插件适合你！</p></li><li><p><a href="https://www.spigotmc.org/resources/townywild.107829/" target="_blank" rel="noreferrer">TownyWild</a> - 离开 Towny 城镇时对郊区进行限时保护。</p></li><li><p><a href="https://github.com/thatguycy/WorldDynamics-Engine" target="_blank" rel="noreferrer">WorldDynamics Engine</a> - 这个插件是一款精妙的角色扮演与特色插件，专为地缘政治服务器打造。允许玩家沉浸于动态的政治地形、资源管理、参与外交，用他们的想法改变世界。</p></li><li><p><a href="https://www.spigotmc.org/resources/thegoldeconomy-1-18-1-20-6-simple-gold-based-economy.102242/" target="_blank" rel="noreferrer">TheGoldEconomy</a> - 一款简单的基于金锭的物品经济插件。</p></li></ul><h2 id="使用了元数据的插件" tabindex="-1">使用了元数据的插件 <a class="header-anchor" href="#使用了元数据的插件" aria-label="Permalink to &quot;使用了元数据的插件&quot;">​</a></h2><ul><li><p><a href="https://github.com/JayAvery/floristics" target="_blank" rel="noreferrer">Floristics</a> - 为 Minecraft 添加了自然植物生长的插件，使用了 Towny 的元数据限制或阻止城镇内的植被生长。</p></li><li><p><a href="https://www.spigotmc.org/resources/townymusic.106049/" target="_blank" rel="noreferrer">TownyMusic</a> - 允许利用 <a href="https://www.spigotmc.org/resources/noteblockapi.19287/" target="_blank" rel="noreferrer">NoteBlockAPI</a> 在城镇内播放音乐。</p></li><li><p><a href="https://www.spigotmc.org/resources/towny-spawn-menu.105225/" target="_blank" rel="noreferrer">Towny Spawn Menu</a> - 添加了城镇菜单，允许浏览或传送至不同的城镇。</p></li><li><p><a href="https://modrinth.com/plugin/quarters" target="_blank" rel="noreferrer">Quarters</a> - 允许城镇拥有者在城镇中设置立体的“居住空间”，可以由玩家租用。</p></li><li><p><a href="https://github.com/SulkyWhale/TownyPersistentToggle" target="_blank" rel="noreferrer">TownyPersistentToggle</a> - 保持 Towny 居民的模式及相关 HUD 界面在服务器重启或玩家退出时保持不变的插件，利用了 Towny 元数据存储不同玩家的界面相关设置。</p></li></ul>',7)),t(o),t(a)])}const k=n(p,[["render",w]]);export{m as __pageData,k as default};
